                         <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                    </div>
                    <div>
                        <div className="font-bold text-lg">Náhodný trénink</div>
                        <div className="text-sm text-gray-500 font-normal">Okamžitá kontrola</div>
                    </div>
                </button>

                <button onClick={() => setMode(AppMode.MISTAKES)} disabled={currentMistakes.length === 0} className={getMenuButtonClass(currentMistakes.length > 0 ? "bg-white hover:bg-orange-50 text-orange-700" : "bg-gray-100 text-gray-400 cursor-not-allowed")}>
                    <div className={`${currentMistakes.length > 0 ? 'bg-orange-100' : 'bg-gray-200'} p-3 rounded-full`}>
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                    </div>
                    <div>
                        <div className="font-bold text-lg">Oprava chyb</div>
                        <div className="text-sm font-normal">{currentMistakes.length} chyb v paměti</div>
                    </div>
                </button>

                <button onClick={() => setMode(AppMode.BROWSER)} className={getMenuButtonClass("bg-white hover:bg-indigo-50 text-indigo-700")}>
                     <div className="bg-indigo-100 p-3 rounded-full">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </div>
                    <div>
                        <div className="font-bold text-lg">Prohlížet otázky</div>
                        <div className="text-sm text-gray-500 font-normal">Databáze otázek</div>
                    </div>
                </button>
            </div>
        </div>
      )}

      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && (
          <TestRunner 
            key={subject + mode} 
            mode={mode} 
            mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined}
            onComplete={handleTestComplete}
            onExit={() => setMode(AppMode.MENU)}
            initialQuestionsForMode={currentQuestions}
            initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined}
            initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined}
          />
      )}

      {subject && mode === AppMode.BROWSER && renderBrowser()}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Question, AppMode } from '../types';

interface Props {
  question: Question;
  mode: AppMode;
  onAnswer: (questionId: number, selectedIndex: number, isCorrect: boolean) => void;
  showFeedback: boolean; // For training mode or review
  userAnswer?: number | null; // Previous answer if reviewing
}

export const QuestionCard: React.FC<Props> = ({
  question,
  mode,
  onAnswer,
  showFeedback,
  userAnswer
}) => {
  const [selected, setSelected] = useState<number | null>(userAnswer ?? null);
  const [isImgError, setIsImgError] = useState(false);

  useEffect(() => {
    setSelected(userAnswer ?? null);
    setIsImgError(false);
  }, [question, userAnswer]);

  const handleSelect = (index: number) => {
    if (showFeedback && selected !== null) return;
    if (mode === AppMode.REVIEW) return;

    setSelected(index);
    const isCorrect = index === question.correctAnswerIndex;
    onAnswer(question.id, index, isCorrect);
  };

  const getOptionClass = (index: number) => {
    const base = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center gap-3 ";

    if (mode === AppMode.MOCK_TEST) {
      return base + (selected === index 
        ? "border-blue-500 bg-blue-50 text-blue-900 ring-2 ring-blue-200" 
        : "border-gray-200 hover:bg-gray-50 text-gray-700");
    }

    if (showFeedback || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) {
        if (selected === null && mode !== AppMode.REVIEW) return base + "border-gray-200 hover:bg-gray-50 text-gray-700";

        if (index === question.correctAnswerIndex) {
            return base + "border-green-500 bg-green-50 text-green-900 ring-2 ring-green-200 font-medium";
        }
        if (selected === index && index !== question.correctAnswerIndex) {
            return base + "border-red-500 bg-red-50 text-red-900 ring-2 ring-red-200";
        }
        return base + "border-gray-200 opacity-60";
    }

    return base + "border-gray-200";
  };

  const imgUrl = question.imageUrl ? `/${question.imageUrl}` : undefined;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 max-w-3xl mx-auto mb-6">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-lg font-semibold text-gray-900 leading-relaxed">
          <span className="text-blue-600 mr-2">#{question.id}</span>
          {question.text}
        </h3>
      </div>

      {question.imageUrl && !isImgError && (
        <div className="mb-6 rounded-lg overflow-hidden border border-gray-200 bg-gray-50 min-h-[200px] flex items-center justify-center relative">
          <img 
            src={imgUrl} 
            alt="Ilustrace k otázce" 
            className="w-full h-auto max-h-80 object-contain mx-auto"
            onError={() => setIsImgError(true)}
          />
        </div>
      )}

      {question.imageUrl && isImgError && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-center">
              <p className="text-red-800 font-bold text-sm mb-2">Obrázek se nepodařilo načíst.</p>

              <div className="text-red-700 text-xs space-y-2 text-left bg-white/50 p-3 rounded">
                  <p><strong>Diagnostika:</strong></p>
                  <p>Aplikace hledá soubor na adrese: <br/><code className="bg-red-100 px-1 py-0.5 rounded">{imgUrl}</code></p>

                  <div className="border-t border-red-200 pt-2 mt-2">
                    <p className="font-semibold">Možné příčiny (Render.com běží na Linuxu):</p>
                    <ul className="list-disc list-inside mt-1 space-y-1">
                        <li>Velká/malá písmena v názvu složky (musí být <code>sps</code>, ne <code>SPS</code>).</li>
                        <li>Velká/malá písmena v názvu souboru (musí být <code>q{question.id}.png</code>, ne <code>Q{question.id}.png</code>).</li>
                        <li>Přípona souboru (musí být <code>.png</code> malými písmeny, ne <code>.PNG</code> nebo <code>.jpg</code>).</li>
                    </ul>
                  </div>

                  <div className="pt-2 text-center">
                      <a 
                        href={imgUrl} 
                        target="_blank" 
                        rel="noreferrer"
                        className="text-blue-600 underline font-semibold hover:text-blue-800"
                      >
                          Zkusit otevřít obrázek v novém okně
                      </a>
                  </div>
              </div>
          </div>
      )}

      <div className="space-y-3">
        {question.options.map((opt, idx) => (
          <button
            key={idx}
            onClick={() => handleSelect(idx)}
            disabled={((mode === AppMode.TRAINING || mode === AppMode.MISTAKES) && selected !== null) || mode === AppMode.REVIEW}
            className={getOptionClass(idx)}
          >
            <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 
                ${selected === idx ? 'border-current' : 'border-gray-300'}`}>
                {selected === idx && <div className="w-2.5 h-2.5 rounded-full bg-current" />}
            </div>
            <span>{opt}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

