const IMAGE_KEYWORDS = ["obrázku", "náčrtu", "vidíš", "schéma", "diagram", "pozice", "kóta"];

const parseQuestions = (raw: any[], subject: 'SPS' | 'STT'): Question[] => {
  return raw.map(item => {
    const [id, text, options, correct] = item;
    const hasImage = IMAGE_KEYWORDS.some(k => text.toLowerCase().includes(k));

    return {
      id,
      text,
      options,
      correctAnswerIndex: correct,
      // Základní cesta (relativní, malá písmena)
      imageUrl: hasImage ? `images/${subject.toLowerCase()}/q${id}.png` : undefined
    };
  });
