    // Očekávaný formát: images/sps/q1.png

    // Pokud cesta nezačíná lomítkem, přidáme varianty s lomítkem i bez
    const path = originalUrl.startsWith('/') ? originalUrl.slice(1) : originalUrl;

    return [
        path,                                       // 1. images/sps/q1.png (Relativní)
        `/${path}`,                                 // 2. /images/sps/q1.png (Absolutní od rootu)
